def ueberstunden(stunden_liste):
    summe = 0
    for stunden in stunden_liste:
        if stunden > 8:
            summe += stunden - 8
    return summe

CREATE TABLE Abteilung (
    AbtID       INT PRIMARY KEY,
    Bezeichnung VARCHAR(50) NOT NULL
);

CREATE TABLE Mitarbeiter (
    MaID     INT PRIMARY KEY,
    Vorname  VARCHAR(50),
    Nachname VARCHAR(50) NOT NULL,
    AbtID    INT,
    FOREIGN KEY (AbtID)
        REFERENCES Abteilung(AbtID)
);

CREATE TABLE Zeitbuchung (
    BuchungID INT PRIMARY KEY,
    MaID      INT NOT NULL,
    Datum     DATE NOT NULL,
    Stunden   DECIMAL(4,2),
    FOREIGN KEY (MaID)
        REFERENCES Mitarbeiter(MaID)
);

